#define NOMINMAX
#include <windows.h>
#include <wincodec.h>
#include <wrl/client.h>
#include "modules/visuals/bloom/native/NativeImages.h"
#include <filesystem>
#include <fstream>
#include <iostream>
using namespace vanta::modules::bloom;
using Microsoft::WRL::ComPtr;
void check(HRESULT result){if(FAILED(result))throw std::runtime_error("Native PNG encoder failed");}
void png(const std::filesystem::path&file,const Array<int>&pixels,int width,int height){
 if(pixels.size()!=std::size_t(width)*height)throw std::runtime_error("Raster size mismatch");
 ComPtr<IWICImagingFactory> factory;check(CoCreateInstance(CLSID_WICImagingFactory,nullptr,CLSCTX_INPROC_SERVER,IID_PPV_ARGS(&factory)));
 ComPtr<IWICStream> stream;check(factory->CreateStream(&stream));check(stream->InitializeFromFilename(file.c_str(),GENERIC_WRITE));
 ComPtr<IWICBitmapEncoder> encoder;check(factory->CreateEncoder(GUID_ContainerFormatPng,nullptr,&encoder));check(encoder->Initialize(stream.Get(),WICBitmapEncoderNoCache));
 ComPtr<IWICBitmapFrameEncode> frame;ComPtr<IPropertyBag2> props;check(encoder->CreateNewFrame(&frame,&props));check(frame->Initialize(props.Get()));check(frame->SetSize(width,height));WICPixelFormatGUID format=GUID_WICPixelFormat32bppBGRA;check(frame->SetPixelFormat(&format));
 if(format!=GUID_WICPixelFormat32bppBGRA)throw std::runtime_error("PNG encoder changed color layout");
 std::vector<int> storage(pixels.begin(),pixels.end());check(frame->WritePixels(height,width*4,width*height*4,reinterpret_cast<BYTE*>(storage.data())));check(frame->Commit());check(encoder->Commit());
 std::cout<<file.filename().string()<<" "<<width<<"x"<<height<<'\n';
}
int main(int argc,char**argv){try{
 if(argc!=2)throw std::runtime_error("Supply the output asset directory");check(CoInitializeEx(nullptr,COINIT_MULTITHREADED));std::filesystem::path out=std::filesystem::absolute(argv[1]);std::filesystem::create_directories(out);
 auto fx=facet::a();png(out/"effects.png",fx,1024,1024);auto levels=facet::d(fx);if(levels.size()!=5||levels[4].size()!=4096)throw std::runtime_error("Invalid FX mip chain");
 for(int cell=0;cell<27;++cell){std::uint64_t alpha=0;for(int y=0;y<facet::CH[cell];++y)for(int x=0;x<facet::CS[cell];++x)alpha+=std::uint32_t(fx[(facet::CY[cell]+y)*1024+facet::CX[cell]+x])>>24;if(!alpha)throw std::runtime_error("Empty FX cell");}
 auto flowers=palette::a();auto branches=branch::a(flowers);png(out/"petals.png",branches,1024,2048);
 {std::ofstream f(out/"petal-anchors.bin",std::ios::binary);f.write("WBA1",4);auto count=static_cast<std::uint32_t>(branch::am.size());f.write(reinterpret_cast<const char*>(&count),4);for(auto value:branch::am)f.write(reinterpret_cast<const char*>(&value),4);if(!f||count==0||count%11)throw std::runtime_error("Invalid branch anchors");std::cout<<count/11<<" branch anchors\n";}
 png(out/"sky-galaxy.png",span::a(1),3084,2056);png(out/"sky-glow.png",span::h(),1024,1024);png(out/"sky-haze.png",slice::a(),1024,256);
 png(out/"sky-clouds.png",strata::c(),256,5120);png(out/"sky-moon.png",strata::g(),1024,1024);png(out/"sky-ribbons.png",ribbon::a(),256,1024);png(out/"sky-celestial.png",sector::a(),512,256);
 auto stars=span::q(7231977);auto colors=span::r(7231977);{std::ofstream f(out/"sky-stars.bin",std::ios::binary);f.write("WBS1",4);for(auto v:stars)f.write(reinterpret_cast<const char*>(&v),4);for(auto v:colors)f.write(reinterpret_cast<const char*>(&v),4);if(!f)throw std::runtime_error("Star data write failed");}
 CoUninitialize();std::cout<<"All assets generated by native C++ kernels.\n";return 0;
 }catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
